using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // ───────────────────────────────────────────────
    //  CalculateTotal – DataRow (compile-time data)
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "Basic total with 10% tax")]
    [DataRow(0.00, 5, 0.10, 0.00, DisplayName = "Zero unit price")]
    [DataRow(25.50, 0, 0.08, 0.00, DisplayName = "Zero quantity")]
    [DataRow(9.99, 1, 0.00, 9.99, DisplayName = "No tax")]
    [DataRow(50.00, 3, 1.00, 300.00, DisplayName = "100% tax rate")]
    [DataRow(100.00, 1, 0.075, 107.50, DisplayName = "7.5% tax rate")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    //  CalculateTotal – invalid inputs
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Negative tax rate")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax rate above 1")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – DynamicData (runtime data)
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> ApplyDiscountData =>
    [
        [100m, 0m, 100m, "No discount"],
        [100m, 10m, 90m, "10% off"],
        [100m, 50m, 50m, "50% off"],
        [100m, 100m, 0m, "100% off (free)"],
        [200m, 25m, 150m, "25% off $200"],
        [49.99m, 15m, 42.4915m, "Fractional result"],
    ];

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountData), DynamicDataDisplayName = nameof(GetApplyDiscountDisplayName))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static string GetApplyDiscountDisplayName(MethodInfo methodInfo, object?[] data)
        => $"{methodInfo.Name} – {data[3]}";

    // ───────────────────────────────────────────────
    //  ApplyDiscount – invalid discount percentages
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Discount below 0")]
    [DataRow(100.01, DisplayName = "Discount above 100")]
    public void ApplyDiscount_WithInvalidPercent_ThrowsArgumentOutOfRange(double discountPercent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }
}

